import{_ as t,o,c as d,ae as r}from"./chunks/framework.CeK7r8F_.js";const p=JSON.parse('{"title":"DOM-ORM Performance Plan","description":"","frontmatter":{},"headers":[],"relativePath":"performance/plan.md","filePath":"performance/plan.md"}'),a={name:"performance/plan.md"};function s(c,e,i,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="dom-orm-performance-plan" tabindex="-1">DOM-ORM Performance Plan <a class="header-anchor" href="#dom-orm-performance-plan" aria-label="Permalink to &quot;DOM-ORM Performance Plan&quot;">​</a></h1><p><strong>Status:</strong> Complete. Scope + target confirmed (Q1–Q12). Implementation order: baseline → compiled hydrator → Phase 2 → Phase 3 → Phase 5. All in-scope workstreams (A–D) are done; the <code>findAll()</code> 3× gate was re-scoped to ~1.3× (Q12) as it is allocation-bound and unreachable.</p><h2 id="_0-results-so-far" tabindex="-1">0. Results so far <a class="header-anchor" href="#_0-results-so-far" aria-label="Permalink to &quot;0. Results so far&quot;">​</a></h2><h3 id="workstream-a-—-compiled-hydrator-done" tabindex="-1">Workstream A — compiled hydrator (DONE) <a class="header-anchor" href="#workstream-a-—-compiled-hydrator-done" aria-label="Permalink to &quot;Workstream A — compiled hydrator (DONE)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>op</th><th>baseline</th><th>compiled</th><th>speedup</th></tr></thead><tbody><tr><td><code>findAll()</code> cached</td><td>968 ms</td><td><strong>800 ms</strong></td><td><strong>1.21×</strong></td></tr><tr><td>— denormalize</td><td>844 ms (87%)</td><td><strong>686 ms (86%)</strong></td><td>1.23×</td></tr><tr><td><code>find($id)</code> cached</td><td>100 ms</td><td>100 ms</td><td>1.0× (needs Phase 2)</td></tr><tr><td><code>findAll()</code> memory peak</td><td>~202 MB</td><td><strong>112 MB</strong></td><td>—</td></tr></tbody></table><ul><li><strong>Parity:</strong> compiled vs reflection produce byte-identical objects for all 50 K records (sha256 match). Tests: green (the pre-existing Vcs failure was fixed). phpstan + ecs clean.</li><li><strong>Key finding:</strong> hydration is <strong>allocation-bound, not reflection-bound</strong>. The generated mapper&#39;s floor is ~11.7 µs/record (object allocation + constructor); reflection only added ~5 µs/record on top. So the compiled hydrator saves ~23% on denormalize, and the <code>findAll()</code> floor is ~704 ms (1.37×). <strong>The 3× / 320 ms <code>findAll()</code> gate (Q11) is not reachable</strong> — it assumed hydration → ~0, which is false. The big remaining wins are <code>find($id)</code> (Phase 2, ~10×) and memory (Phase 3, &lt;100 MB).</li></ul><h3 id="workstream-b-—-chunked-cache-phase-2-done" tabindex="-1">Workstream B — chunked cache (Phase 2, DONE) <a class="header-anchor" href="#workstream-b-—-chunked-cache-phase-2-done" aria-label="Permalink to &quot;Workstream B — chunked cache (Phase 2, DONE)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>op</th><th>baseline</th><th>chunked</th><th>speedup</th></tr></thead><tbody><tr><td><code>findAll()</code> cached</td><td>968 ms</td><td><strong>697 ms</strong></td><td><strong>1.39×</strong></td></tr><tr><td>— array-build (payload load)</td><td>38 ms</td><td>9.3 ms</td><td>4×</td></tr><tr><td><code>find($id)</code> cached</td><td>100 ms</td><td><strong>0.39 ms</strong></td><td><strong>256×</strong></td></tr></tbody></table><ul><li><strong>Layout:</strong> <code>{cache_path}/../cache/</code> holds <code>meta.php</code> (fingerprint), <code>index.php</code> (inverted index), <code>all.php</code> (monolith payload for full scans), and 256 shard files <code>{00..ff}.php</code> keyed by <code>crc32(id) &amp; 0xff</code>. Point lookups load one shard (~1/256th of the data); full scans load <code>all.php</code> (one require, so <code>findAll()</code> does not regress from the 256-shard fan-out).</li><li><strong>Why crc32, not <code>substr(id,0,2)</code>:</strong> DOM-ORM ids are hex-encoded ASCII, so the first two chars only span 16 values — <code>crc32</code> spreads any distribution across all 256 shards.</li><li><strong>Parity:</strong> compiled vs reflection still byte-identical (sha256 <code>2b0d0bea…</code> unchanged). Tests: green (the pre-existing Vcs failure was fixed). phpstan + ecs clean.</li><li><strong><code>find($id)</code> gate (≤10 ms / 10×) met 25× over.</strong> <code>findAll()</code> is now at the hydration floor (1.39×); the 3× gate remains unreachable (Workstream A finding).</li></ul><h3 id="workstream-c-—-lazy-result-sets-phase-3-done" tabindex="-1">Workstream C — lazy result sets (Phase 3, DONE) <a class="header-anchor" href="#workstream-c-—-lazy-result-sets-phase-3-done" aria-label="Permalink to &quot;Workstream C — lazy result sets (Phase 3, DONE)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>op</th><th>materialized</th><th>lazy</th><th>memory</th></tr></thead><tbody><tr><td><code>findAll()</code> / <code>findAllLazy()</code> 50 K</td><td>114 MB</td><td><strong>16.3 MB</strong></td><td><strong>−86%</strong></td></tr><tr><td>— after touching 1 K entities</td><td>114 MB</td><td><strong>16.3 MB</strong></td><td>flat</td></tr><tr><td><code>findAllLazy()-&gt;all()</code> (full touch)</td><td>114 MB</td><td>114 MB</td><td>same (expected)</td></tr></tbody></table><ul><li><strong>Design:</strong> <code>LazyCollection</code> (additive, per Q6) wraps the <code>ChunkStore</code> + a small <code>ids.php</code> (ordered id list, ~1.6 MB). <code>count()</code> is O(1); <code>get()</code> / <code>first()</code> / <code>last()</code> / <code>map()</code> / <code>filter()</code> hydrate on first access and cache. Memory is flat in records <em>touched</em>, not records <em>found</em>.</li><li><strong><code>findByLazy()</code>:</strong> resolves candidate ids from the inverted index (same as <code>findBy()</code>), then wraps them in a <code>LazyCollection</code>. The index is large (~142 MB in memory for 39 K distinct city values) — that cost is inherent to index-backed lookups and shared with <code>findBy()</code>. The lazy collection adds only ~16 MB on top (vs ~114 MB materialized).</li><li><strong>Parity:</strong> lazy entities are byte-identical to materialized (sampled). Tests: no new failures (only the pre-existing Vcs one). phpstan + ecs clean.</li><li><strong>Memory gate (&lt;100 MB) met</strong> for the lazy path: <code>findAllLazy()</code> is 16.3 MB. The materialized <code>findAll()</code> remains 114 MB (allocation-bound, Workstream A).</li></ul><h3 id="workstream-d-—-benchmark-gates-phase-5-done" tabindex="-1">Workstream D — benchmark + gates (Phase 5, DONE) <a class="header-anchor" href="#workstream-d-—-benchmark-gates-phase-5-done" aria-label="Permalink to &quot;Workstream D — benchmark + gates (Phase 5, DONE)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>gate</th><th>target</th><th>actual</th><th>status</th></tr></thead><tbody><tr><td><code>find($id)</code> latency</td><td>≤ 10 ms</td><td><strong>0.02 ms</strong></td><td>✅ PASS (5015×)</td></tr><tr><td><code>find($id)</code> speedup</td><td>≥ 10×</td><td><strong>5015×</strong></td><td>✅ PASS</td></tr><tr><td><code>findAll()</code> cached latency</td><td>≤ 320 ms</td><td>718 ms</td><td>❌ FAIL (unreachable)</td></tr><tr><td><code>findAll()</code> cached speedup</td><td>≥ 3×</td><td>1.35×</td><td>❌ FAIL (unreachable)</td></tr><tr><td>memory <code>findAll</code> 50 K (materialized)</td><td>&lt; 100 MB</td><td>114.1 MB</td><td>❌ FAIL</td></tr><tr><td>memory <code>findAll</code> 50 K (<strong>lazy</strong>)</td><td>&lt; 100 MB</td><td><strong>16.3 MB</strong></td><td>✅ PASS</td></tr></tbody></table><ul><li><strong>Harness:</strong> <code>benchmarks/compare/phase5-bench.php</code> (time, median of 10) + <code>phase5-memory.php</code> (memory, fresh processes) + <code>phase5-generate.php</code> (500 K dataset). JSON → <code>.profile/results/phase5-gates.json</code>.</li><li><strong>500 K memory sanity:</strong> <code>findAllLazy()</code> is <strong>115.8 MB</strong> (the <code>ids.php</code> is 24 MB, 10× the 50 K&#39;s 2.4 MB) vs ~1.1 GB materialized — a ~10× reduction.</li><li><strong>Vcs test fixed</strong> (was a pre-existing FatalException halting the suite): <code>GitAdapter</code> is <code>final</code>, so the test now injects the binary via the constructor instead of sub-classing. Full suite green: <strong>182 passed, 0 failed</strong>.</li><li><strong>Full gate table + reproduction steps:</strong> <code>benchmarks/compare/charts/PHASE5-GATES.md</code>.</li></ul><h2 id="_1-problem-evidence" tabindex="-1">1. Problem &amp; evidence <a class="header-anchor" href="#_1-problem-evidence" aria-label="Permalink to &quot;1. Problem &amp; evidence&quot;">​</a></h2><p>DOM-ORM reads entities from <code>data.xml</code> via a pre-compiled PHP array cache (<code>cache.php</code> payload + <code>cache-index.php</code> inverted indexes). Point lookups are already fast (index-backed, ~2 ms warm), but two hot spots remain.</p><p><strong>Baseline profile</strong> (50 K records, PHP 8.5.4, libxml2 2.15.2, opcache-warm):</p><table tabindex="0"><thead><tr><th>op</th><th>require (payload load)</th><th>array-build</th><th>denormalize (hydration)</th><th>total</th></tr></thead><tbody><tr><td><code>findAll()</code></td><td>87 ms (9%)</td><td>38 ms (4%)</td><td><strong>844 ms (87%)</strong></td><td>968 ms</td></tr><tr><td><code>find($id)</code></td><td><strong>98 ms (98%)</strong></td><td>—</td><td>0.1 ms (0.1%)</td><td>100 ms</td></tr></tbody></table><p>No-cache <code>findAll()</code> (XML path): read 7 ms, loadXML 76 ms, xpath 85 ms, decode 411 ms (29%), denormalize 858 ms (60%), total 1424 ms.</p><p><strong>Two distinct bottlenecks, two distinct fixes:</strong></p><ul><li><code>findAll()</code> is dominated by <strong>hydration</strong> — <code>SchemaDenormalizer::instantiateEntity()</code> calls <code>new \\ReflectionMethod($ret, $method)</code> per field, per record (<code>src/Serializer/Normalizer/SchemaDenormalizer.php:237</code>). → <strong>compiled hydrator</strong>.</li><li><code>find($id)</code> is dominated by <strong>loading the whole payload</strong> — <code>QueryCache::load()</code><code>require</code>s the entire 50 K <code>cache.php</code> to fetch one row. → <strong>chunked cache (Phase 2)</strong>.</li></ul><h2 id="_2-scope" tabindex="-1">2. Scope <a class="header-anchor" href="#_2-scope" aria-label="Permalink to &quot;2. Scope&quot;">​</a></h2><p><strong>In scope (core) — all done:</strong></p><ul><li><strong>Compiled hydrator</strong> — build-time generated mapper, runtime reflection fallback.</li><li><strong>Phase 2</strong> — chunked cache (256 crc32 shards). LRU eviction deferred.</li><li><strong>Phase 3</strong> — lazy result sets (<code>LazyCollection</code>). Ghost objects deferred.</li><li><strong>Phase 5</strong> — benchmark + gates (verification).</li></ul><p><strong>Out of scope / deferred:</strong></p><ul><li>Phase 2 LRU eviction (<code>cache_max_bytes</code> configured, enforcement deferred).</li><li>Phase 3 ghost objects + SAX streaming (<code>LazyCollection</code> alone meets the memory gate).</li><li>Phase 4 (incremental writes) — not the target.</li><li>Phase 6 (resident runtimes / Swoole/RoadRunner).</li><li>XPath anchoring (<code>//</code> → anchored) — only ~6% of no-cache, 0% cached; optional micro-opt.</li></ul><h2 id="_3-acceptance-gates-q11" tabindex="-1">3. Acceptance gates (Q11) <a class="header-anchor" href="#_3-acceptance-gates-q11" aria-label="Permalink to &quot;3. Acceptance gates (Q11)&quot;">​</a></h2><p>Measured at 50 K (primary) + 500 K (memory sanity), opcache-warm, via the project benchmark harness:</p><ul><li><code>findAll()</code> (cached, warm): <strong>≤ ⅓ of baseline</strong> (≥3×). Baseline ~968 ms → <strong>≤ ~320 ms</strong>.</li><li><code>find($id)</code> (cached, warm): <strong>≥10×</strong> → <strong>≤ 10 ms</strong>.</li><li>Memory peak during <code>findAll()</code> (50 K): <strong>&lt; 100 MB</strong> (baseline ~200 MB) via lazy result sets.</li><li><strong>No regressions</strong> on <code>findBy</code>/<code>findOneBy</code> (index-backed) and the write path.</li></ul><p>Recorded in <code>benchmarks/compare/charts/PHASE5-GATES.md</code> (Phase 5, DONE).</p><h2 id="_4-workstream-a-—-compiled-hydrator" tabindex="-1">4. Workstream A — Compiled hydrator <a class="header-anchor" href="#_4-workstream-a-—-compiled-hydrator" aria-label="Permalink to &quot;4. Workstream A — Compiled hydrator&quot;">​</a></h2><p><strong>Goal:</strong> eliminate per-field reflection from hydration (87% of <code>findAll()</code>).</p><p><strong>Design (Q8 = A):</strong></p><ul><li>At <code>build-cache</code>, generate a plain PHP mapper per entity class: <code>storage/generated/{entityType}.php</code>.</li><li>The mapper is a function <code>dom_orm_hydrate_{entityType}(array $row): EntityInterface</code> that: <ul><li>reads constructor params directly (inlined cast/decrypt/json/datetime — no reflection);</li><li><code>new $class(...$args)</code>;</li><li>sets id;</li><li>sets remaining properties via direct setter calls;</li><li>handles fragments (typed scalar arrays) and groups.</li></ul></li><li>File meta carries a <strong>hash of the entity class signature</strong> (properties + types + ctor params + attributes + source mtime). On load, mismatch → regenerate (self-healing). Regen is triggered when the <strong>entity file is modified</strong> (Q8).</li><li><strong>Fallback:</strong> if no generated file, or it can&#39;t be written, <code>SchemaDenormalizer::instantiateEntity()</code> uses the current reflection path. Pure speedup, never breaks.</li><li><strong>Integration:</strong> <code>instantiateEntity()</code> checks for a valid generated mapper first; else reflection.</li><li><strong>Config:</strong> <code>dom-orm.hydrator</code> = <code>auto</code> (default) | <code>reflection</code> | <code>compiled</code>. <code>auto</code> = use generated mapper if valid, else reflection.</li></ul><p><strong>Files:</strong></p><ul><li>New: <code>src/Storage/HydratorGenerator.php</code> (signature hash + code emission).</li><li>New: <code>src/Storage/Hydrator.php</code> (load/validate/dispatch generated mapper).</li><li>Modify: <code>src/Serializer/Normalizer/SchemaDenormalizer.php</code> (dispatch to mapper, reflection fallback).</li><li>Modify: <code>src/Storage/QueryCache.php</code> / build-cache command (call generator).</li><li>Modify: <code>src/helpers.php</code> (new <code>hydrator</code> config key).</li></ul><p><strong>Correctness:</strong> the generated mapper must exactly replicate <code>instantiateEntity</code> semantics (ctor param order, casts, decryption, json, datetime, fragment typing, group handling, sensitive fields). Covered by the existing serializer tests + a new parity test (generated vs reflection produce identical objects).</p><h2 id="_5-workstream-b-—-phase-2-chunked-cache" tabindex="-1">5. Workstream B — Phase 2: chunked cache <a class="header-anchor" href="#_5-workstream-b-—-phase-2-chunked-cache" aria-label="Permalink to &quot;5. Workstream B — Phase 2: chunked cache&quot;">​</a></h2><p><strong>Goal:</strong> <code>find($id)</code> loads one chunk, not the whole payload (98% → ~0%).</p><p><strong>Implemented (Q9):</strong></p><ul><li>Replaced the monolithic <code>cache.php</code> with a chunked directory under <code>{cache_path}/../cache/</code>: <code>meta.php</code> (fingerprint), <code>index.php</code> (inverted index), <code>all.php</code> (full payload for scans), <code>ids.php</code> (ordered id list), and 256 shard files <code>{00..ff}.php</code> keyed by <code>crc32(id) &amp; 0xff</code> (one <code>return [...]</code> per file → opcache-friendly).</li><li><strong>Sharding:</strong> 256 shards via <code>crc32(id) &amp; 0xff</code> (not a 2-hex prefix, which only spans 16 values for hex-encoded ids).</li><li><strong><code>findBy</code>:</strong> equality-only (as today); the index resolves candidate ids, shards materialize.</li><li><strong>Full scans:</strong> <code>findAll()</code> loads <code>all.php</code> in one <code>require</code> so it does not pay a 256-shard fan-out.</li><li><strong>Migration (Q2):</strong> one-time rebuild. Legacy monolithic <code>cache.php</code> detected on load → rebuilt to chunks exactly once.</li><li><strong>Deferred:</strong> LRU eviction (<code>cache_max_bytes</code> config, default 64 MB, is present but not yet enforced) and the <code>put</code>/<code>get</code>/<code>delete</code>/<code>evict</code> per-entity cache API.</li></ul><p><strong>Files:</strong></p><ul><li>Modify: <code>src/Storage/QueryCache.php</code> (chunked read/write).</li><li>New: <code>src/Storage/ChunkStore.php</code> (shard resolution + atomic write).</li><li>Modify: <code>src/helpers.php</code> (<code>cache_max_bytes</code> config).</li></ul><h2 id="_6-workstream-c-—-phase-3-lazy-result-sets" tabindex="-1">6. Workstream C — Phase 3: lazy result sets <a class="header-anchor" href="#_6-workstream-c-—-phase-3-lazy-result-sets" aria-label="Permalink to &quot;6. Workstream C — Phase 3: lazy result sets&quot;">​</a></h2><p><strong>Goal:</strong> <code>findAll()</code> returns immediately; memory stays flat.</p><p><strong>Implemented (Q10):</strong></p><ul><li>New <code>src/Repository/LazyCollection.php</code>: <code>IteratorAggregate + Countable + ArrayAccess</code> over the <code>ChunkStore</code> + the ordered <code>ids.php</code>. <code>count()</code> is <strong>O(1)</strong>.</li><li>New additive repository methods: <code>findAllLazy(): ?LazyCollection</code>, <code>findByLazy(array $criteria): ?LazyCollection</code>. <strong>Existing <code>findAll()</code>/<code>findBy()</code> keep exact signatures + materialized behavior</strong> (Q1/Q6).</li><li><code>get()</code> / <code>first()</code> / <code>last()</code> / <code>map()</code> / <code>filter()</code> hydrate on first access and cache; memory is flat in records <em>touched</em>, not records <em>found</em>.</li><li><strong>Interaction with chunks:</strong> <code>find($id)</code> = one shard + compiled mapper. <code>findAllLazy()</code> = wrap the ordered id list; shards load lazily on access.</li><li><strong>Deferred:</strong> ghost objects (<code>ReflectionClass::newLazyGhost()</code>) and SAX streaming. The lazy collection alone meets the memory gate (16.3 MB @50K), so neither was needed.</li></ul><p><strong>Files:</strong></p><ul><li>New: <code>src/Repository/LazyCollection.php</code>.</li><li>Modify: <code>src/Repository/AbstractEntityRepository.php</code> (add <code>findAllLazy</code>/<code>findByLazy</code>).</li></ul><h2 id="_7-workstream-d-—-phase-5-benchmark-gates" tabindex="-1">7. Workstream D — Phase 5: benchmark + gates <a class="header-anchor" href="#_7-workstream-d-—-phase-5-benchmark-gates" aria-label="Permalink to &quot;7. Workstream D — Phase 5: benchmark + gates&quot;">​</a></h2><ul><li>Use <code>benchmarks/compare/</code> harness + <code>dom-orm perf</code>.</li><li>Re-baseline after each workstream; record in <code>benchmarks/compare/charts/PHASE5-GATES.md</code>.</li><li>Gates (Section 3) must be green before the plan is &quot;done.&quot;</li><li>Each workstream ends with a green test suite (pest, phpstan, ecs).</li></ul><h2 id="_8-implementation-order" tabindex="-1">8. Implementation order <a class="header-anchor" href="#_8-implementation-order" aria-label="Permalink to &quot;8. Implementation order&quot;">​</a></h2><ol><li><strong>Baseline</strong> — capture current numbers (bench2.php + perf) into <code>benchmarks/compare/charts/BASELINE.md</code>.</li><li><strong>Workstream A — compiled hydrator</strong> (biggest <code>findAll()</code> win; self-contained).</li><li><strong>Workstream B — Phase 2 chunked cache</strong> (<code>find($id)</code> win).</li><li><strong>Workstream C — Phase 3 lazy result sets</strong> (memory + deferral).</li><li><strong>Workstream D — Phase 5 gates</strong> (prove + record).</li></ol><h2 id="_9-config-surface-new-keys" tabindex="-1">9. Config surface (new keys) <a class="header-anchor" href="#_9-config-surface-new-keys" aria-label="Permalink to &quot;9. Config surface (new keys)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>default</th><th>purpose</th></tr></thead><tbody><tr><td><code>dom-orm.hydrator</code></td><td><code>auto</code></td><td><code>auto</code> / <code>reflection</code> / <code>compiled</code></td></tr><tr><td><code>dom-orm.cache_max_bytes</code></td><td><code>67108864</code> (64 MB)</td><td>LRU eviction budget</td></tr></tbody></table><p>(Chunk dir + generated dir are derived from <code>cache_path</code>&#39;s directory.)</p><h2 id="_10-risks-mitigations" tabindex="-1">10. Risks &amp; mitigations <a class="header-anchor" href="#_10-risks-mitigations" aria-label="Permalink to &quot;10. Risks &amp; mitigations&quot;">​</a></h2><ul><li><strong>Generated-mapper correctness</strong> → parity test (generated vs reflection identical) + full existing suite.</li><li><strong>Index/chunk divergence (concurrency)</strong> → flock (existing) + self-healing chunk rebuild + concurrency tests.</li><li><strong>LazyCollection edge cases</strong> → tests for <code>count()</code>, iteration, <code>ArrayAccess</code>, partial access.</li><li><strong>opcache immutability of chunk files</strong> → one <code>return [...]</code> per file (already the pattern).</li></ul><h2 id="_11-decisions-log" tabindex="-1">11. Decisions log <a class="header-anchor" href="#_11-decisions-log" aria-label="Permalink to &quot;11. Decisions log&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Q</th><th>Decision</th></tr></thead><tbody><tr><td>Q1</td><td>API unchanged; new behavior additive/config-driven</td></tr><tr><td>Q2</td><td>One-time cache rebuild OK</td></tr><tr><td>Q3</td><td>build-cache on write only for <code>on_persist</code> (default <code>manual</code> self-heals on read); graceful fallback OK</td></tr><tr><td>Q4</td><td>Drop PHP 8.3; floor 8.4 (ghosts deferred)</td></tr><tr><td>Q5</td><td>2–3× faster = success; lower memory a plus</td></tr><tr><td>Q6</td><td>Additive new methods OK</td></tr><tr><td>Q7</td><td>Scope = compiled hydrator + Phase 2 + Phase 3 + Phase 5; defer Phase 4/6 + XPath anchoring (ghosts + LRU deferred within 2/3)</td></tr><tr><td>Q8</td><td>Compiled hydrator = build-time file + runtime reflection fallback; regen on entity-file change (signature hash)</td></tr><tr><td>Q9</td><td>64 MB LRU budget (deferred); 256-shard crc32 sharding; equality-only findBy</td></tr><tr><td>Q10</td><td>LazyCollection; O(1) count() (ghosts deferred)</td></tr><tr><td>Q11</td><td>Gates: findAll ≤ 320 ms, find(id) ≤ 10 ms, mem &lt; 100 MB @50K; 50K primary + 500K memory sanity</td></tr><tr><td>Q12</td><td>Re-scope the <code>findAll()</code> gate to ~1.3× (allocation-bound, 3× unreachable)</td></tr></tbody></table>',61)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
